package com.tekwatt.reporting.controller;
import com.tekwatt.reporting.dto.*;import com.tekwatt.reporting.entity.*;import com.tekwatt.reporting.service.ReportingService;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/reports") public class ReportController {private final ReportingService service;public ReportController(ReportingService service){this.service=service;}@PostMapping @ResponseStatus(HttpStatus.CREATED)ReportResponse create(@Valid @RequestBody CreateReportRequest request){return service.create(request);}@GetMapping("/{id}")ReportResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping Page<ReportResponse>list(@RequestParam UUID tenantId,Pageable pageable){return service.list(tenantId,pageable);}@GetMapping("/{id}/download")ResponseEntity<byte[]>download(@PathVariable UUID id){Report report=service.getEntity(id);if(report.getStatus()!=ReportStatus.COMPLETED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Report is not ready");return ResponseEntity.ok().contentType(MediaType.parseMediaType(report.getContentType())).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+report.getFileName()+"\"").body(report.getFileContent());}}
